/// A curve row at a fractional internal amount `x`, at grey level `v` (both interpolated).
fn curve(rows: &[[f32; STEPS]], from: f32, x: f32, v: f32) -> f32 {
    if v >= 1.0 {
        return 1.0;
    }
    let r = ((x - from) / 10.0).clamp(0.0, (rows.len() - 1) as f32);
    let i = (r as usize).min(rows.len() - 2);
    let t = r - i as f32;
    let at = |row: &[f32; STEPS]| {
        let p = v.max(0.0) * (STEPS - 1) as f32;
        let j = (p as usize).min(STEPS - 2);
        let s = p - j as f32;
        row[j] + (row[j + 1] - row[j]) * s
    };
    at(&rows[i]) * (1.0 - t) + at(&rows[i + 1]) * t
}

/// Whites at internal amount `x` (−100 … 270) of grey level `v`.
pub(crate) fn whites(v: f32, x: f32) -> f32 {
    curve(&WHITES, WHITES_FROM, x, v)
}

/// Blacks at internal amount `x` (−100 … 100) of grey level `v`.
pub(crate) fn blacks(v: f32, x: f32) -> f32 {
    curve(&BLACKS, BLACKS_FROM, x, v)
}

/// The least Blacks adaptation on photographs.
const PHOTO_BLACKS: f32 = 1.2;

/// Bilinear lookup of an adaptation table at black point `bp` and white point `wp`.
fn adapt(table: &[[f32; 8]; 9], bp: f32, wp: f32) -> f32 {
    let idx = |grid: &[f32], v: f32| {
        let v = v.clamp(grid[0], grid[grid.len() - 1]);
        let i = grid.windows(2).position(|w| v <= w[1]).unwrap_or(grid.len() - 2);
        (i, (v - grid[i]) / (grid[i + 1] - grid[i]))
    };
    let (i, s) = idx(&BPS, bp);
    let (j, t) = idx(&WPS, wp);
    let row = |i: usize| table[i][j] * (1.0 - t) + table[i][j + 1] * t;
    row(i) * (1.0 - s) + row(i + 1) * s
}

/// The internal amounts of the Whites and Blacks sliders (−100 … 100) for an image whose 1st
/// and 99th luminance percentiles are the grey levels `bp` and `wp` (sRGB-encoded).
pub(crate) fn amounts(whites: f32, blacks: f32, bp: f32, wp: f32) -> (f32, f32) {
    let w = if whites > 0.0 { whites * adapt(&AW, bp, wp) } else { whites };
    // On photographs Photoshop's Blacks is about 1.2 times the block images' amount even where
    // their black point is 0 (ten public-domain photos: 1.08–1.36).
    let b = if blacks < 0.0 { blacks * adapt(&AB, bp, wp).max(PHOTO_BLACKS) } else { blacks };
    (w.clamp(-100.0, 270.0), b.clamp(-100.0, 100.0))
}

/// Applies Whites and Blacks (internal amounts `w`, `b`) to straight RGBA pixels (`width` per
/// row) encoded with `enc`. Values above 1 (float documents) keep their excess.
pub(crate) fn apply(px: &mut [[f32; 4]], width: usize, w: f32, b: f32, enc: Encoding) {
    if w == 0.0 && b == 0.0 {
        return;
    }
    // A grey level's new level, both sRGB-encoded.
    let grey = |v: f32| {
        let v = if w != 0.0 { whites(v, w) } else { v };
        if b != 0.0 { blacks(v, b) } else { v }
    };
    let per_channel = w > 0.0 || b < 0.0;
    par_rows(px, width, 1, |_, row| {
        for q in row.iter_mut() {
            let lin = [0, 1, 2].map(|c| enc.decode(q[c]));
            if per_channel {
                for c in 0..3 {
                    let over = (lin[c] - 1.0).max(0.0);
                    q[c] = enc.encode(super::srgb_decode(grey(super::srgb_encode(lin[c].min(1.0)))) + over);
                }
            } else {
                let y = super::luma_linear(lin).max(0.0);
                if y <= 1e-7 {
                    continue;
                }
                let y2 = super::srgb_decode(grey(super::srgb_encode(y.min(1.0)))) + (y - 1.0).max(0.0);
                let k = y2 / y;
                for c in 0..3 {
                    q[c] = enc.encode(lin[c] * k);
                }
            }
        }
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn full_range_rows_match_photoshop() {
        // Photoshop 25.4 on a 64-level block image spanning black to white (sRGB levels).
        assert!((whites(97.1 / 255.0, 100.0) * 255.0 - 137.4).abs() < 0.6);
        assert!((whites(194.3 / 255.0, -100.0) * 255.0 - 167.6).abs() < 0.6);
        assert!((blacks(97.1 / 255.0, -100.0) * 255.0 - 60.0).abs() < 0.6);
        assert!((blacks(48.6 / 255.0, 100.0) * 255.0 - 67.0).abs() < 0.6);
        // The compressing directions keep black and white.
        assert_eq!(whites(1.0, -100.0), 1.0);
        assert_eq!(blacks(0.0, 100.0), 0.0);
    }

    #[test]
    fn the_clipping_directions_adapt_to_the_image() {
        // A dark, low-contrast image needs more: Whites +50 acts like +94.5 on [0.05, 0.6].
        let (w, _) = amounts(50.0, 0.0, 0.05, 0.6);
        assert!((w - 94.5).abs() < 2.0, "{w}");
        // A raised black point strengthens Blacks −40 to −58 on [0.6, 1].
        let (_, b) = amounts(0.0, -40.0, 0.6, 1.0);
        assert!((b + 58.0).abs() < 1.0, "{b}");
        // Never below the photographs' 1.2.
        assert!((amounts(0.0, -50.0, 0.0, 1.0).1 + 60.0).abs() < 1e-3);
        // The compressing directions never adapt.
        assert_eq!(amounts(-50.0, 50.0, 0.3, 0.6), (-50.0, 50.0));
    }
}
